// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address rewardToken, uint256 amount, uint256 depositETH) public {
        vm.assume(rewardToken != address(0));
        vm.assume(amount > 0 && amount <= type(uint216).max);
        vm.assume(depositETH <= 100 ether);

        // Add reward token
        c.addReward(rewardToken);

        // Get totalSupply before any stake
        uint256 supplyBefore = c.totalSupply();

        // Send ETH to the contract (this changes address(this).balance but not stakes)
        vm.deal(address(c), depositETH);

        // Get totalSupply after ETH deposit
        uint256 supplyAfter = c.totalSupply();

        // The rule: totalSupply must not change when ETH is sent to the contract
        assertTrue(supplyBefore == supplyAfter, "totalSupply changed after ETH deposit");
    }
}

